//
// The benchmark scene pack (docs/benchmark.md "The scene pack"; sculptforge --benchmark-pack DIR): a folder with a
// manifest, pack.json, and the sculpts it names (our own, generated by tools/starter, CC0). Each scene is a project
// file divided a fixed number of times, so every machine builds the same mesh from a download of a few hundred KB.
#pragma once

#include "core/Mesh.h"

#include <string>
#include <vector>

namespace sf {

inline constexpr const char* kBenchPackSchema = "sculptforge-bench-pack/1";

struct BenchPackScene {
    std::string id;      // "creature-floor": the run's label in the result and on the website
    std::string title;   // what a person reads
    std::string file;    // the project beside pack.json (a plain file name)
    std::string tier;    // the hardware tier the scene is meant for: "floor", "standard" or "high" (a label; the run is not limited to it)
    int divide = 0;      // subdivision levels added to the sculpt (each one makes four times the triangles)
    double triangles = 0; // what the mesh has after dividing (checked when it is built; the memory check before)
};

struct BenchPack {
    std::string dir;       // where pack.json is
    std::string name;
    int version = 0;
    std::string strokeSet; // the strokes every scene gets ("pack/1": the standard strokes of proof mode)
    std::string sha256;    // of pack.json then every scene's file, in manifest order: what a result says it ran
    std::vector<BenchPackScene> scenes;
};

// Reads DIR/pack.json and checks it against the files: schema, unique ids, plain file names that exist, divide 0-8, a tier
// and a triangle count for every scene. False with the reason in `error`.
bool loadBenchPack(const std::string& dir, BenchPack& pack, std::string& error);

// Opens the scene's project (its Parts merged), divides it `divide` times and returns the mesh. The triangle count
// must equal the manifest's, else the pack was altered or the app divides differently (an error either way).
bool buildBenchPackScene(const BenchPack& pack, const BenchPackScene& scene, Mesh& out, std::string& error);

} // namespace sf
